  case RecurKind::FAdd: {
    // res = fmul v, n
    Value *Scale = ConstantFP::get(VectorizedValue->getType(), Cnt);
    LLVM_DEBUG(dbgs() << "SLP: FAdd (to-fmul) " << Cnt << "of "
                      << VectorizedValue << ". (HorRdx)\n");
    return Builder.CreateFMul(VectorizedValue, Scale);
