source_filename = "final_bug_test.ll"

; This test shows the bug: fast-math flags are not preserved
; when converting repeated fadd to fmul

define float @src(float %a) {
  %1 = fadd fast float %a, %a
  %2 = fadd fast float %1, %a
  %3 = fadd fast float %2, %a
  %4 = fadd fast float %3, %a
  ret float %4
}

; The optimization produces this (without fast flag):
define float @tgt_bug(float %a) {
  %1 = fmul float %a, 5.000000e+00
  ret float %1
}

; But it should produce this (with fast flag):
define float @tgt_correct(float %a) {
  %1 = fmul fast float %a, 5.000000e+00
  ret float %1
}
EOF"}

{"command":"opt -S -passes=slp-vectorizer -slp-optimize-identity-hor-reduction-ops -o - << 'EOF'
